51	// routeSnapshots dispatches /v1/snapshots and its sub-paths.
52	func (s *store) routeSnapshots(w http.ResponseWriter, r *http.Request) {
53		parts := splitPath(r.URL.Path, snapshotPath)
54		for _, seg := range parts {
55			if seg == "" {
56				writeError(w, http.StatusNotFound, "not_found")
57				return
58			}
59		}
60		switch {
61		case len(parts) == 0:
62			if r.Method != http.MethodGet {
63				methodNotAllowed(w, http.MethodGet)
64				return
65			}
66			s.listSnapshots(w)
67		case len(parts) == 1:
68			switch r.Method {
69			case http.MethodGet:
70				s.getSnapshot(w, parts[0])
71			case http.MethodDelete:
72				s.deleteSnapshot(w, parts[0])
73			default:
74				methodNotAllowed(w, http.MethodGet, http.MethodDelete)
75			}
76		case len(parts) == 2 && parts[1] == "clones":
77			if r.Method != http.MethodPost {
78				methodNotAllowed(w, http.MethodPost)
79				return
80			}
81			s.createClone(w, r, parts[0])
82		default:
83			writeError(w, http.StatusNotFound, "not_found")
84		}
85	}
