121	// createSnapshot handles POST /v1/volumes/{volumeId}/snapshots.
122	func (s *store) createSnapshot(w http.ResponseWriter, r *http.Request, volumeID string) {
123		var in createSnapshotInput
124		if !decodeRequest(r, &in) {
125			writeError(w, http.StatusBadRequest, "invalid_request")
126			return
127		}
128		if !validID(volumeID) || !validID(in.ID) || in.ExpectedGeneration == nil || *in.ExpectedGeneration < 0 {
129			writeError(w, http.StatusBadRequest, "invalid_request")
130			return
131		}
132		expected := *in.ExpectedGeneration
133	
134		s.mu.Lock()
135		defer s.mu.Unlock()
136		// A retry of the same id wins its idempotency/conflict check before the
137		// source is looked up, so deleting the source after a successful snapshot
138		// keeps the retry returning 200.
139		if existing, dup := s.snapshots[in.ID]; dup {
140			if existing.sourceVolumeID == volumeID && existing.sourceGeneration == expected {
141				writeJSON(w, http.StatusOK, existing.view())
142				return
143			}
144			writeError(w, http.StatusConflict, "snapshot_exists")
145			return
146		}
147		v, ok := s.volumes[volumeID]
148		if !ok {
149			writeError(w, http.StatusNotFound, "volume_not_found")
150			return
151		}
152		if v.binding != "" {
153			writeError(w, http.StatusConflict, "volume_in_use")
154			return
155		}
156		if v.generation != expected {
157			writeError(w, http.StatusConflict, "stale_generation")
158			return
159		}
160		p := s.pools[v.poolID]
161		// The store lock makes the quota and capacity checks plus the charge
162		// atomic, so concurrent snapshots can never exceed either limit. The
163		// snapshot inherits the source volume's tenant.
164		if p.tenantQuotaExceeded(v.tenant, v.sizeBytes) {
165			writeError(w, http.StatusConflict, "tenant_quota_exceeded")
166			return
167		}
168		if p.allocated() > p.rawCapacity-v.sizeBytes {
169			writeError(w, http.StatusConflict, "insufficient_capacity")
170			return
171		}
172		snap := &snapshot{
173			id:               in.ID,
174			sourceVolumeID:   volumeID,
175			poolID:           v.poolID,
176			sizeBytes:        v.sizeBytes,
177			sourceGeneration: v.generation,
178			tenant:           v.tenant,
179		}
180		s.snapshots[in.ID] = snap
181		p.snapshotBytes += v.sizeBytes
182		p.tenantUsed[v.tenant] += v.sizeBytes
183		s.appendAudit(auditSnapshotCreated, snapshotPath+"/"+in.ID, v.poolID, v.sizeBytes)
184		writeJSON(w, http.StatusCreated, snap.view())
185	}
