196			writeError(w, http.StatusNotFound, "snapshot_not_found")
197			return
198		}
199		s.pools[snap.poolID].snapshotBytes -= snap.sizeBytes
200		s.pools[snap.poolID].tenantUsed[snap.tenant] -= snap.sizeBytes
201		delete(s.snapshots, id)
202		s.appendAudit(auditSnapshotDeleted, snapshotPath+"/"+id, snap.poolID, -snap.sizeBytes)
203		w.WriteHeader(http.StatusNoContent)
204	}
