207	func (s *store) createClone(w http.ResponseWriter, r *http.Request, snapshotID string) {
208		var in createCloneInput
209		if !decodeRequest(r, &in) {
210			writeError(w, http.StatusBadRequest, "invalid_request")
211			return
212		}
213		if !validID(snapshotID) || !validID(in.ID) || !validID(in.PoolID) {
214			writeError(w, http.StatusBadRequest, "invalid_request")
215			return
216		}
217	
218		s.mu.Lock()
219		defer s.mu.Unlock()
220		snap, ok := s.snapshots[snapshotID]
221		if !ok {
222			writeError(w, http.StatusNotFound, "snapshot_not_found")
223			return
224		}
225		// A clone is an ordinary volume, so its id shares the global volume
226		// namespace. Once the snapshot is confirmed, the volume-id conflict check
227		// decides: a retry from the same snapshot into the same pool is 200, while
228		// an id owned by any other creation or a different pool is 409.
229		if existing, dup := s.volumes[in.ID]; dup {
230			if existing.cloneSource == snapshotID && existing.poolID == in.PoolID {
231				writeJSON(w, http.StatusOK, existing.view())
232				return
233			}
234			writeError(w, http.StatusConflict, "volume_exists")
235			return
236		}
237		target, ok := s.pools[in.PoolID]
238		if !ok {
239			writeError(w, http.StatusNotFound, "pool_not_found")
240			return
241		}
242		// The clone inherits the snapshot's tenant and charges the target pool.
243		if target.tenantQuotaExceeded(snap.tenant, snap.sizeBytes) {
