243	func TestConcurrentResizeOnlyOneWins(t *testing.T) {
244		h := Handler()
245		createPool(t, h, volPool)
246		createVol(t, h, `{"id":"vol1","poolId":"vp","sizeBytes":100}`)
247	
248		const goroutines = 30
249		var wg sync.WaitGroup
250		statuses := make(chan int, goroutines)
251		wg.Add(goroutines)
252		for i := 0; i < goroutines; i++ {
253			go func(i int) {
254				defer wg.Done()
255				// Every request uses the same current generation but distinct
256				// target sizes; capacity still admits every individual grow.
257				body := fmt.Sprintf(`{"sizeBytes":%d,"expectedGeneration":0}`, 200+i)
258				statuses <- do(h, http.MethodPut, "/v1/volumes/vol1/size", body).Code
259			}(i)
260		}
261		wg.Wait()
262		close(statuses)
263		var ok200, stale int
264		for code := range statuses {
265			switch code {
266			case http.StatusOK:
267				ok200++
268			case http.StatusConflict:
269				stale++
270			default:
271				t.Fatalf("unexpected status %d", code)
272			}
273		}
274		if ok200 != 1 || stale != goroutines-1 {
275			t.Fatalf("200=%d stale=%d", ok200, stale)
276		}
277		v := decodeBody(t, do(h, http.MethodGet, "/v1/volumes/vol1", ""))
278		if v["generation"].(float64) != 1 {
279			t.Fatalf("generation after concurrent resize = %v", v["generation"])
280		}
281		// Pool accounting matches exactly one grow to a size within [200,229].
282		p := decodeBody(t, do(h, http.MethodGet, "/v1/storage-pools/vp", ""))
283		allocated := p["allocatedBytes"].(float64)
284		if allocated != v["sizeBytes"].(float64) || allocated < 200 || allocated > 229 {
285			t.Fatalf("inconsistent accounting: pool=%v volume=%v", allocated, v["sizeBytes"])
286		}
